        'update.dlfail' = 'ดาวน์โหลดไม่สำเร็จ: {0}'
        'update.howto' = "{0} อยู่ในโฟลเดอร์ Downloads และค่า SHA256 ตรงกับ release แล้ว`n`nวิธีอัปเดต: สำรองไฟล์ก่อน เปิด AME Wizard แล้วลากไฟล์นี้เข้าไป การตั้งค่า Akati OS Center ยังอยู่ครบ"
        'doc.refresh.ok' = '{0} Hz สูงสุดของจอนี้แล้ว'
        'doc.refresh.bad' = 'จอใช้ {0} Hz อยู่ แต่ทำได้ถึง {1} Hz'
        'doc.fix.refresh' = 'ใช้ค่าสูงสุด'
        'doc.xmp.ok' = 'แรมทำงานที่ความเร็วเต็มสเปก ({0} MT/s)'
        'doc.xmp.bad' = 'แรมทำงานที่ {0} MT/s แต่ทำได้ถึง {1} MT/s (ยังไม่ได้เปิด XMP หรือ EXPO)'
        'doc.fix.xmp' = 'วิธีเปิด'
        'doc.xmp.howto' = "แรมของเครื่องนี้วิ่งได้เร็วกว่าตอนนี้ ความเร็วเต็มสเปกเป็นโปรไฟล์ใน BIOS: บอร์ด Intel เรียกว่า XMP บอร์ด AMD เรียกว่า EXPO (หรือ DOCP)`n`n1. รีสตาร์ตเครื่องแล้วเข้า BIOS (ส่วนใหญ่กด Delete หรือ F2 ตอนเปิดเครื่อง)`n2. หา XMP, EXPO หรือ DOCP (มักอยู่หน้าแรก หรือในเมนู Memory / AI Tweaker / OC)`n3. เลือก Profile 1 แล้วบันทึกและออก (ส่วนใหญ่กด F10)`n`nถ้าเปิดเครื่องไม่ขึ้นหลังตั้ง เครื่องจะกลับไปใช้ค่าเดิมเองหลังลองไม่กี่ครั้ง หรือล้างค่า BIOS (CMOS) ได้ Akati OS ไม่แก้ BIOS ให้"
        'boost.services' = 'พัก service เบื้องหลังจนกว่าจะหยุดบูสต์เกม (ทำดัชนีค้นหา, SysMain, งานพิมพ์, การดาวน์โหลดของ Windows Update)'
