        'doc.rebar.howto' = "Resizable BAR ทำให้ CPU เข้าถึงหน่วยความจำของการ์ดจอได้ทั้งหมดในครั้งเดียว บางเกมเร็วขึ้นไม่กี่เปอร์เซ็นต์ บางเกมไม่ต่าง`n`n1. รีสตาร์ตเครื่องแล้วเข้า BIOS (ส่วนใหญ่กด Delete หรือ F2 ตอนเปิดเครื่อง)`n2. เปิด Above 4G Decoding (บางบอร์ดเรียก Above 4GB MMIO)`n3. เปิด Resizable BAR (หรือ Re-Size BAR Support บนบอร์ด AMD อาจเรียก Smart Access Memory)`n4. ต้องปิด CSM (legacy boot) ให้ Windows บูตแบบ UEFI`n5. บันทึกและออก (ส่วนใหญ่กด F10)`n`nบอร์ดหรือการ์ดจอรุ่นเก่าอาจต้องอัปเดต BIOS หรือเฟิร์มแวร์ก่อน Akati OS ไม่แก้ BIOS ให้"
