        'doc.xmp.howto' = "RAM của bạn có thể chạy nhanh hơn hiện tại. Tốc độ cao hơn là một cấu hình trong BIOS: XMP trên bo mạch Intel, EXPO (hoặc DOCP) trên bo mạch AMD.`n`n1. Khởi động lại PC và vào BIOS (thường nhấn Delete hoặc F2 khi khởi động).`n2. Tìm XMP, EXPO hoặc DOCP (thường ở trang đầu hoặc trong Memory / AI Tweaker / OC).`n3. Chọn Profile 1, lưu và thoát (thường nhấn F10).`n`nNếu PC không khởi động được sau đó, nó sẽ tự quay lại cài đặt cũ sau vài lần thử, hoặc bạn có thể xóa cài đặt BIOS (CMOS). Akati OS không thay đổi BIOS."
