        'doc.rebar.howto' = "Resizable BAR cho phép CPU truy cập toàn bộ bộ nhớ card đồ họa cùng lúc. Một số game nhanh hơn vài phần trăm, số khác không thay đổi.`n`n1. Khởi động lại PC và vào BIOS (thường nhấn Delete hoặc F2 khi khởi động).`n2. Bật Above 4G Decoding (đôi khi gọi là Above 4GB MMIO).`n3. Bật Resizable BAR (còn gọi là Re-Size BAR Support, hoặc Smart Access Memory trên bo mạch AMD).`n4. Phải tắt CSM (legacy boot) để Windows khởi động ở chế độ UEFI.`n5. Lưu và thoát (thường nhấn F10).`n`nBo mạch và card đồ họa cũ có thể cần cập nhật BIOS hoặc firmware trước. Akati OS không thay đổi BIOS."
