        'doc.rebar.howto' = "Resizable BAR membuat CPU bisa menjangkau seluruh memori kartu grafis sekaligus. Beberapa game jadi sedikit lebih cepat, yang lain tidak berubah.`n`n1. Restart PC dan buka BIOS (biasanya tekan Delete atau F2 saat menyala).`n2. Nyalakan Above 4G Decoding (kadang disebut Above 4GB MMIO).`n3. Nyalakan Resizable BAR (juga disebut Re-Size BAR Support, atau Smart Access Memory di board AMD).`n4. CSM (legacy boot) harus mati, agar Windows menyala dalam mode UEFI.`n5. Simpan dan keluar (biasanya F10).`n`nBoard dan kartu grafis lama mungkin perlu pembaruan BIOS atau firmware dulu. Akati OS tidak mengubah BIOS."
